  'Creators must provide accurate titles, descriptions, categories, languages, thumbnails, captions, visibility, and scheduling settings. Scheduled videos are not public until their scheduled time and successful processing.' => 'सिर्जनाकर्ताहरूले सही शीर्षकहरू, विवरणहरू, कोटीहरू, भाषाहरू, थम्बनेलहरू, क्याप्सनहरू, दृश्यता, र समय तालिका सेटिङहरू प्रदान गर्नुपर्छ। अनुसूचित भिडियोहरू तिनीहरूको निर्धारित समय र सफल प्रशोधन नभएसम्म सार्वजनिक हुँदैनन्।',
