  'Other' => 'अन्य',
  'Partnerships, press, and platform operations.' => 'साझेदारी, प्रेस, र प्लेटफर्म सञ्चालनहरू।',
  'Payment help' => 'भुक्तानी मद्दत',
  'Platform' => 'प्लेटफर्म',
  'Playback' => 'प्लेब्याक',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'प्लेब्याक प्रगति, पछि हेर्ने अवस्था, मनपर्ने, टिप्पणीहरू, सदस्यताहरू, अधिसूचनाहरू, र प्रशासक विश्लेषणहरू डाटाबेसमा भण्डारण गरिन्छन् जब प्रमाणीकृत प्लेटफर्म सुविधाहरूमा लिङ्क गरिन्छ।',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'प्लेब्याक, टिप्पणीहरू, लाइकहरू, पछि हेर्नुहोस्, सदस्यताहरू, सूचनाहरू, सन्देशहरू, प्लेलिस्टहरू, र भाषा सेटिङहरू मुख्य नेभिगेसन र खाता मेनु मार्फत उपलब्ध छन्।',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub एउटा खाताबाट सिर्जनाकर्ता सामग्री अपलोड गर्न, हेर्ने, समयतालिका बनाउन, व्यवस्थापन गर्ने र मध्यस्थ गर्ने भिडियो प्लेटफर्म हो।',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub यस डिप्लोइमेन्टमा चलिरहेको भिडियो प्लेटफर्म हो, सिर्जनाकर्ताहरू, दर्शकहरू, समुदायहरू र प्लेटफर्म अपरेटरहरूका लागि बनाइएको हो।',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub ले एउटै प्लेटफर्मबाट सिर्जनाकर्ता च्यानलहरू, भिडियो अपलोडहरू, निर्धारित प्रकाशनहरू, सदस्यताहरू, टिप्पणीहरू, प्लेलिस्टहरू, पछि हेर्नुहोस्, प्रत्यक्ष सामग्री पृष्ठहरू, र प्रशासन उपकरणहरू प्रदान गर्दछ।',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub ले लगइन सत्रहरू, API प्रमाणीकरण, CSRF/सुरक्षा व्यवहार, भाषा चयन, विषयवस्तु चयन, खाता मेनु स्थिति, र अनुप्रयोगले काम गर्न आवश्यक अन्य सुविधाहरूको लागि आवश्यक कुकीहरू र ब्राउजर भण्डारण प्रयोग गर्दछ।',
  'playhub_language, theme' => 'playhub_language, विषयवस्तु',
  'Popular questions' => 'लोकप्रिय प्रश्नहरू',
  'Preference storage' => 'प्राथमिकता भण्डारण',
  'Privacy Policy' => 'गोपनीयता नीति',
  'Privacy, cookie, account security, support messages, and moderation data are handled through the policies and backend records connected to PlayHub.' => 'गोपनीयता, कुकी, खाता सुरक्षा, समर्थन सन्देशहरू, र मध्यस्थता डेटा नीतिहरू र PlayHub मा जडान ब्याकइन्ड रेकर्डहरू मार्फत ह्यान्डल गरिन्छ।',
  'Profile, login, security, and settings help.' => 'प्रोफाइल, लगइन, सुरक्षा, र सेटिङ मद्दत।',
