  'Public JSON endpoints include /api/health for deployment status and /api/upload-options for upload categories, languages, limits, chunk size, and trending tags.' => 'सार्वजनिक JSON अन्तिम बिन्दुहरूमा तैनाती स्थितिको लागि /api/स्वास्थ्य र अपलोड कोटीहरू, भाषाहरू, सीमाहरू, खण्ड आकार, र ट्रेन्डिङ ट्यागहरूका लागि /api/upload-options समावेश छन्।',
