  'Refund handling for paid PlayHub features depends on billing records attached to this deployment.' => 'भुक्तान गरिएको PlayHub सुविधाहरूको लागि फिर्ता ह्यान्डलिङ यस परिनियोजनमा संलग्न वास्तविक बिलिङ रेकर्डहरूमा निर्भर गर्दछ।',
  'Refund handling is tied to billing records and administrator review. If billing is not configured for this deployment, there is no platform charge to refund.' => 'रिफन्ड ह्यान्डलिंग वास्तविक बिलिङ रेकर्ड र प्रशासक समीक्षासँग जोडिएको छ। यदि यो डिप्लोइमेन्टको लागि बिलिङ कन्फिगर गरिएको छैन भने, फिर्ता गर्न कुनै प्लेटफर्म शुल्क छैन।',
