  'Select a reason' => 'कारण छान्नुहोस्',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'एक वा बढी भिडियो फाइलहरू चयन गर्नुहोस्, आवश्यक विवरणहरू प्रविष्ट गर्नुहोस्, कोटी र भाषा छनौट गर्नुहोस्, थम्बनेल थप्नुहोस्, दृश्यता छनौट गर्नुहोस्, र प्रकाशित गर्नुहोस्। सर्भरले प्रक्रिया सुरु गर्नु अघि ठूला फाइलहरू टुक्रामा अपलोड हुन्छन्।',
  'Send a message and it will be saved for admins.' => 'सन्देश पठाउनुहोस् र यो प्रशासकहरूको लागि सुरक्षित हुनेछ।',
  'Send billing details to admin support for review.' => 'समीक्षाको लागि प्रशासक समर्थनलाई बिलिङ विवरणहरू पठाउनुहोस्।',
  'Send message' => 'सन्देश पठाउनुहोस्',
  'Send order details through the refund popup.' => 'फिर्ता पपअप मार्फत अर्डर विवरणहरू पठाउनुहोस्।',
  'Send us a message' => 'हामीलाई सन्देश पठाउनुहोस्',
  'Sending...' => 'पठाउँदै...',
  'Server configured' => 'सर्भर कन्फिगर गरियो',
