  'session, token' => 'सत्र, टोकन',
  'Settings and login' => 'सेटिङ र लगइन',
  'Short summary' => 'संक्षिप्त सारांश',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'साइन इन गर्नुहोस् र खाता, प्रोफाइल, पासवर्ड, सूचना, गोपनीयता, र सिर्जनाकर्ता प्राथमिकताहरूको लागि सेटिङहरू प्रयोग गर्नुहोस्। सिर्जनाकर्ता अपलोड र सामग्री समस्याहरूले भिडियो शीर्षक, च्यानल, ब्राउजर, र अपलोड पृष्ठमा देखाइएको कुनै पनि प्रक्रिया त्रुटि समावेश गर्नुपर्छ।',
  'Sign in for account support' => 'खाता समर्थनको लागि साइन इन गर्नुहोस्',
  'Signed in' => 'साइन इन गरियो',
  'Start uploading' => 'अपलोड गर्न सुरु गर्नुहोस्',
  'Still can’t find an answer?' => 'अझै जवाफ पाउन सकिएन?',
  'Stored for admins' => 'प्रशासकहरूको लागि भण्डारण गरियो',
  'Stores language, theme, and interface preferences.' => 'भण्डारण भाषा, विषयवस्तु, र इन्टरफेस प्राथमिकताहरू।',
  'Studio, playlists, analytics, channels.' => 'स्टुडियो, प्लेलिस्ट, एनालिटिक्स, च्यानलहरू।',
  'Submit a billing or refund message to admin support.' => 'प्रशासक समर्थनमा बिलिङ वा फिर्ता सन्देश पेश गर्नुहोस्।',
  'Submit refund request' => 'फिर्ता अनुरोध पेश गर्नुहोस्',
