  'Technical issue' => 'प्राविधिक समस्या',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'हालको PlayHub API र अपलोड कार्यप्रवाहसँग एकीकरणका लागि प्राविधिक नोटहरू।',
  'Tell us more about your question or request...' => 'हामीलाई आफ्नो प्रश्न वा अनुरोध बारे थप बताउनुहोस्...',
  'Terms of Use' => 'प्रयोगका सर्तहरू',
  'The configured' => 'कन्फिगर गरिएको',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'विकासकर्ता पृष्ठ प्रत्यक्ष Laravel ब्याकएन्डमा जडान गरिएको छ: मार्ग सूची, डाटाबेस गणनाहरू, अपलोड सीमाहरू, र प्लेटफर्म मेटाडेटा /api/developers बाट लोड गरिन्छ।',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'फ्रन्टएन्डले प्राथमिकताहरू भण्डारण गर्दछ जस्तै चयन गरिएको भाषा, विषयवस्तु, प्लेब्याक लाम, हेर्नुहोस् प्रगति, र इन्टरफेस स्थिति ताकि अनुभव पृष्ठ नेभिगेसन र पुन: लोडहरूमा एकरूप रहन्छ।',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'प्रशोधन कार्यले रेन्डिसनहरू सङ्केत गर्दछ, आवश्यक पर्दा थम्बनेलहरू सिर्जना गर्दछ, क्याप्शनहरू भण्डारण गर्दछ, र प्रशोधन पूरा भएपछि भिडियोहरूलाई तयार चिन्ह लगाउँदछ। समयतालिकाले तिनीहरूलाई जारी नगरेसम्म भविष्यमा निर्धारित भिडियोहरू निजी रहन्छन्।',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'अपलोड प्रणाली डाटाबेस-समर्थित छ, API बाट कोटीहरू र भाषाहरूलाई समर्थन गर्दछ, अपलोड गरिएका भिडियोहरू प्रशोधन गर्दछ, थम्बनेलहरू र क्याप्शनहरू भण्डार गर्दछ, र यसको रिलीजको समय नभएसम्म अनुसूचित सामग्री निजी राख्छ।',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'यो पृष्ठले सत्र, सुरक्षा, प्राथमिकताहरू, प्लेब्याक, र प्रमाणीकृत सुविधाहरूको लागि PlayHub ले कुकीहरू र ब्राउजर भण्डारण कसरी प्रयोग गर्दछ भनेर वर्णन गर्दछ।',
