  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'लाइभ PlayHub डेटाको साथ अपलोड, हेर्नुहोस्, सदस्यता लिनुहोस्, मध्यम गर्नुहोस् र निर्माण गर्नुहोस्।',
  'Uploaded videos' => 'अपलोड गरिएका भिडियोहरू',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'अपलोड गरिएका भिडियोहरू प्ले गर्न मिल्ने रेन्डिसनहरूमा इन्कोड गरिएका छन्। प्रशोधन समय फाइल आकार, अवधि, सर्भर लोड, र लाम स्थिति मा निर्भर गर्दछ। अपलोड पृष्ठ र सिर्जनाकर्ता स्टुडियोले भिडियो रेकर्डबाट वास्तविक प्रशोधन स्थिति देखाउँदछ।',
  'Uploads, scheduling, and processing are available.' => 'अपलोड, समयतालिका, र प्रशोधन उपलब्ध छन्।',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'सिर्जनाकर्ता कार्यप्रवाहका लागि /api/भिडियोहरू, च्यानल अन्त्य बिन्दुहरू, र प्रमाणीकृत मार्गहरू प्रयोग गर्नुहोस्।',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'भिडियो र टिप्पणीहरूको लागि अन्तर्निर्मित रिपोर्ट कार्यहरू प्रयोग गर्नुहोस् ताकि प्रशासकहरूले सही सामग्री सन्दर्भ प्राप्त गर्न सकून्। प्रशासक ड्यासबोर्ड पृष्ठहरूले प्रयोगकर्ताहरू, सामग्री, रिपोर्टहरू, मुद्रीकरण, विश्लेषण, समर्थन, भूमिकाहरू, र प्रणाली सेटिङहरूको लागि प्रत्यक्ष डाटाबेस डेटा प्रयोग गर्दछ।',
  'Use Contact Us' => 'हामीलाई सम्पर्क गर्नुहोस् प्रयोग गर्नुहोस्',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'सामान्य API अनुरोधहरूको लागि JSON प्रयोग गर्नुहोस् र फाइल अपलोडहरूको लागि FormData। प्रमाणीकरणलाई बाइपास नगर्नुहोस्: कोटीहरू र भाषाहरू डाटाबेस आईडीहरू हुन्, दृश्यता सार्वजनिक, सूचीबद्ध नगरिएको, वा निजीमा सीमित छ, र क्याप्शनहरूले SRT, VTT, वा TXT फाइलहरू स्वीकार गर्छन्।',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'आफ्नो प्रोफाइल, सुरक्षा, पासवर्ड, दुई-कारक डेलिभरी, यन्त्रहरू, प्राथमिकताहरू, र सूचना विकल्पहरू अद्यावधिक गर्न सेटिङहरू प्रयोग गर्नुहोस्। यदि तपाइँ आफ्नो खाता पहुँच गर्न सक्नुहुन्न भने, लगइन प्रवाह प्रयोग गर्नुहोस् र साइट प्रशासकलाई खाता इमेल प्रदान गर्नुहोस्।',
  'Use the contact form' => 'सम्पर्क फारम प्रयोग गर्नुहोस्',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'भिडियोहरू, टिप्पणीहरू, र सामुदायिक पोस्टहरूमा रिपोर्ट कार्यहरू प्रयोग गर्नुहोस् ताकि प्रशासकहरूले सही सामग्री सन्दर्भ प्राप्त गर्न सकून्।',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'सामग्रीले प्लेटफर्म नियमहरू उल्लङ्घन गर्न सक्छ जब भिडियोहरू, टिप्पणीहरू, र सामुदायिक पोस्टहरूमा रिपोर्ट कार्यहरू प्रयोग गर्नुहोस्। यी रिपोर्टहरू वास्तविक सामग्री रेकर्डमा बाँधिएका छन् र सामान्य सन्देश भन्दा राम्रो छन् किनभने प्रशासकहरूले सही वस्तुको समीक्षा गर्न सक्छन्।',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'खाता मद्दत, सामग्री रिपोर्टहरू, प्राविधिक समस्याहरू, र प्रशासक अनुरोधहरूको लागि सही PlayHub च्यानल प्रयोग गर्नुहोस्।',
  'Video categories' => 'भिडियो कोटिहरू',
  'Video for everyone. Built for creators and viewers.' => 'सबैको लागि भिडियो। वास्तविक प्लेटफर्म डाटाबाट निर्मित।',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'भिडियो अपलोड, समयतालिका, थम्बनेल, र प्रशोधन मुद्दाहरू।',
  'Videos, thumbnails, captions, processing.' => 'भिडियोहरू, थम्बनेलहरू, क्याप्शनहरू, प्रशोधन गर्दै।',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'दर्शकहरूले कोटीहरू ब्राउज गर्न, भिडियोहरू खोज्न, सामग्री हेर्न, च्यानलहरूको सदस्यता लिन, पछि हेर्नका लागि भिडियोहरू बचत गर्न, टिप्पणी गर्न, सूचनाहरू प्राप्त गर्न, र भाषा र पहुँच प्राथमिकताहरू व्यवस्थापन गर्न सक्छन्।',
  'Viewing and community help' => 'अवलोकन र समुदाय मद्दत',
  'Waiting for backend endpoint inventory.' => 'ब्याकएन्ड अन्तिम बिन्दु सूचीको लागि पर्खँदै।',
  'We’re here to help.' => 'हामी मद्दत गर्न यहाँ छौं।',
  'What is PlayHub?' => 'PlayHub के हो?',
  'What PlayHub does' => 'PlayHub ले के गर्छ',
  'Where do contact messages go?' => 'सम्पर्क सन्देशहरू कहाँ जान्छन्?',
  'Why is my video still processing?' => 'मेरो भिडियो किन अझै प्रशोधन भइरहेको छ?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'हो। अपलोड पृष्ठमा नेटिभ तालिका मिति र समय फिल्ड प्रयोग गर्नुहोस्। ब्याकइन्डले शेड्यूल_एट भण्डार गर्छ, भिडियोलाई प्रशोधन गर्छ, मिति भविष्यमा हुँदा यसलाई निजी राख्छ, र लारावेल अनुसूचक निर्धारित समय पछि चल्दा यसलाई जारी गर्दछ।',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'हो। अपलोडमा नेटिभ शेड्यूल फिल्ड प्रयोग गर्नुहोस्। ब्याकइन्डले शेड्यूल_एट भण्डारण गर्छ र समय तालिका पूरा भएपछि भिडियो रिलिज गर्छ।',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'तपाईं अतिथिको रूपमा ब्राउज गर्दै हुनुहुन्छ। खाता-विशिष्ट उपकरणहरू पहुँच गर्न साइन इन गर्नुहोस्।',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'तपाईं आफ्नो खाता प्रमाणहरू, प्रोफाइल गतिविधि, अपलोड सामग्री, टिप्पणीहरू, सन्देशहरू, र तपाईंको खाताबाट प्रदर्शन गरिएका कुनै पनि सिर्जनाकर्ता वा व्यवस्थापक कार्यहरूको लागि जिम्मेवार हुनुहुन्छ। बलियो पासवर्डहरू प्रयोग गर्नुहोस् र दुई-कारक डेलिभरी विधिहरू हालको राख्नुहोस्।',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'तपाईं आफ्नो ब्राउजर सेटिङहरूमा ब्राउजर कुकीहरू र स्थानीय भण्डारण खाली गर्न सक्नुहुन्छ। आवश्यक भण्डारण खाली गर्दा तपाईंलाई साइन आउट गर्न, भाषा/विषय प्राथमिकताहरू रिसेट गर्न, स्थानीय प्लेब्याक स्थिति हटाउन, र तपाईंलाई फेरि लग इन गर्न आवश्यक हुन सक्छ।',
  'You receive a response by email.' => 'तपाईले इमेल मार्फत प्रतिक्रिया प्राप्त गर्नुहुन्छ।',
  'You’re in control' => 'तपाईं नियन्त्रणमा हुनुहुन्छ',
  'Your choices' => 'आफ्नो छनोट',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'तपाईंको सन्देश सीधै वेबसाइट ब्याकइन्डमा बचत गरिएको छ र समर्थन अन्तर्गत प्रशासक ड्यासबोर्डमा देखिन्छ।',
  'Your support' => 'तपाईंको समर्थन',
  'Watch video' => 'भिडियो हेर्नुहोस',
  'Copy link' => 'लिङ्क प्रतिलिपि गर्नुहोस्',
  'View creator' => 'सिर्जनाकर्ता हेर्नुहोस्',
  'Remove from playlist' => 'प्लेलिस्टबाट हटाउनुहोस्',
  'Removing videos from playlists is not available here yet.' => 'प्लेलिस्टहरूबाट भिडियोहरू हटाउन यहाँ अझै उपलब्ध छैन।',
  'Create New Playlist' => 'नयाँ प्लेलिस्ट सिर्जना गर्नुहोस्',
  'Organize your videos into a playlist' => 'तपाईंको भिडियोहरूलाई प्लेलिस्टमा व्यवस्थित गर्नुहोस्',
  'Playlist Name' => 'प्लेलिस्ट नाम',
  'e.g. Travel Vlogs 2025' => 'जस्तै यात्रा भ्लग २०२५',
  '(optional)' => '(वैकल्पिक)',
