  'Tip' => 'टिप',
  'Use playlists to organize your content and make it easier for your audience to discover more videos.' => 'तपाइँको सामग्री संगठित गर्न प्लेलिस्टहरू प्रयोग गर्नुहोस् र तपाइँका दर्शकहरूलाई थप भिडियोहरू पत्ता लगाउन सजिलो बनाउनुहोस्।',
