  'Create your first playlist to organize videos from your channel and saved library.' => 'आफ्नो च्यानल र सुरक्षित पुस्तकालयबाट भिडियोहरू व्यवस्थित गर्न आफ्नो पहिलो प्लेलिस्ट सिर्जना गर्नुहोस्।',
